:root {
  --bg-card: #1a1035;
  --bg-header: #2b1a5e;
  --bg-footer: #120d28;
  --accent-gold: #f5c842;
  --accent-red: #e84040;
  --accent-blue: #4a90e8;
  --accent-green: #3ecf7a;
  --text-primary: #f0ecff;
  --text-muted: #9b8fc0;
  --text-dark: #1a1035;
  --border-subtle: #3d2e6e;
  --tag-class-bg: #3b1f60;
  --tag-aerial-bg: #1a3a5e;
  --tag-ground-bg: #1f4a35;
  --tag-finale-bg: #5e2020;
  --qr-bg: #f0ecff;
  --qr-dot: #1a1035;
  --status-bg: #3ecf7a;
}

.permit-card {
  width: 460px;
  background: var(--bg-card);
  border-radius: 12px;
  border: 1.5px solid var(--border-subtle);
  overflow: hidden;
  font-size: 13px;
}

.permit-header {
  background: var(--bg-header);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 1.5px solid var(--border-subtle);
}

.permit-badge {
  font-size: 24px;
  line-height: 1;
  flex-shrink: 0;
}

.permit-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.permit-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.permit-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.permit-status {
  background: var(--status-bg);
  color: var(--text-dark);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 3px 9px;
  border-radius: 20px;
  flex-shrink: 0;
}

.permit-body {
  display: flex;
  gap: 0;
}

.permit-details {
  flex: 1;
  padding: 11px 14px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  border-right: 1.5px solid var(--border-subtle);
}

.detail-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.detail-key {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.detail-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.permit-meta {
  width: 136px;
  padding: 11px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
}

.permit-id-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  margin: 0;
}

.permit-qr {
  width: 52px;
  height: 52px;
  background: var(--qr-bg);
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--accent-gold);
}

.qr-inner {
  width: 34px;
  height: 34px;
  background:
    repeating-linear-gradient(
      0deg,
      var(--qr-dot) 0px,
      var(--qr-dot) 3px,
      transparent 3px,
      transparent 6px
    ),
    repeating-linear-gradient(
      90deg,
      var(--qr-dot) 0px,
      var(--qr-dot) 3px,
      transparent 3px,
      transparent 6px
    );
  border-radius: 2px;
  opacity: 0.65;
}

.permit-id-num {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.05em;
}

.permit-tags {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.tag {
  font-size: 9px;
  font-weight: 700;
  text-align: center;
  padding: 3px 6px;
  border-radius: 4px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.tag-class {
  background: var(--tag-class-bg);
  color: var(--accent-gold);
  border: 1px solid var(--accent-gold);
}

.tag-aerial {
  background: var(--tag-aerial-bg);
  color: var(--accent-blue);
  border: 1px solid var(--accent-blue);
}

.tag-ground {
  background: var(--tag-ground-bg);
  color: var(--accent-green);
  border: 1px solid var(--accent-green);
}

.tag-finale {
  background: var(--tag-finale-bg);
  color: var(--accent-red);
  border: 1px solid var(--accent-red);
}

.permit-footer {
  background: var(--bg-footer);
  padding: 8px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1.5px solid var(--border-subtle);
}

.footer-authority {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 500;
}

.footer-expiry {
  font-size: 10px;
  color: var(--accent-red);
  font-weight: 700;
}
